render('/','Dojocid — Artes marciais em Copacabana','Dojocid em Copacabana: formação infantil, treino adulto e judô e jiu-jitsu para mulheres. Conheça também o treinamento funcional, uma atividade independente de preparação física.',intro)
for route,title,index,related in [('/judo-e-jiu-jitsu','Judô e Jiu-Jitsu',0,[(3,'Escola de Judô Cid Nascimento'),(1,'Checkmat')]),('/boxe','Boxe',3,[(12,'Registro de treino de boxe no Dojocid'),(2,'Boxe Para Todos — Juan Joseph')])]:
 p=people[index]
 body=f'<section class="page-intro wrap"><a class="back-link" href="/#modalidades">← Todas as modalidades</a><p class="eyebrow">Modalidades · Dojocid</p><h1>{title}</h1><p>Artes marciais em Copacabana</p>{button()}</section><section class="section wrap split profile-feature">{img(p["image"],p["name"],"portrait",True)}<div><p class="eyebrow">Professor</p><h2>{p["name"]}</h2>{bio(p)}<a class="text-link" href="/professores">Conheça toda a equipe →</a></div></section>'
 if route=='/judo-e-jiu-jitsu':
  body+='<section class="wrap audience-callout"><p class="eyebrow">Crianças e adultos</p><h2>Formação e treinamento<br>em diferentes fases da vida.</h2><p>Nas aulas infantis, o foco inclui disciplina, respeito, convivência e desenvolvimento motor. Para adultos, aprendizado técnico e desenvolvimento físico. Consulte a equipe sobre turmas e o treino adequado ao seu objetivo.</p><div class="audience-links"><a class="secondary-button" href="/#infantil">Conheça o pilar infantil ↗</a><a class="secondary-button" href="/#adultos">Conheça o treino adulto ↗</a><a class="secondary-button" href="#mulheres">Judô e Jiu-Jitsu para mulheres ↓</a></div></section>'
  body+=f'<section class="section wrap women-section" id="mulheres"><div class="section-heading"><p class="eyebrow">Judô e Jiu-Jitsu para mulheres</p><h2>Defesa pessoal, técnica<br>e autoconfiança.</h2><p class="women-intro">Com ou sem experiência prévia, você pode iniciar um aprendizado progressivo, respeitando seu condicionamento e seu ritmo. Converse com a equipe sobre a prática mais adequada para você.</p></div><div class="women-topics"><article><h3>Judô: equilíbrio e controle</h3><p>O judô trabalha equilíbrio, deslocamento, projeções, controle corporal e disciplina. O aprendizado valoriza a técnica e o aproveitamento do equilíbrio e da movimentação do oponente.</p></article><article><h3>Jiu-jitsu: posição e movimento</h3><p>No jiu-jitsu, o treino desenvolve controle, posicionamento, escapes e defesa no solo. Alavancas e posicionamento são recursos técnicos; as diferenças de força física continuam a exigir atenção e cuidado.</p></article><article><h3>Segurança e autonomia</h3><p>O aprendizado de defesa pessoal inclui prevenção, percepção corporal e tomada de decisões. Quedas, imobilizações e técnicas de solo são trabalhadas conforme a modalidade, sem garantia de proteção em confrontos reais.</p></article><article><h3>Confiança e preparo físico</h3><p>A prática permite trabalhar força, resistência, mobilidade, coordenação e agilidade. Desafios graduais incentivam concentração, disciplina e confiança, com respeito aos limites e à evolução individual.</p></article></div><div class="women-contact">{audience_contact("Converse sobre as aulas para mulheres","Olá! Quero conhecer as aulas de judô e jiu-jitsu para mulheres no Dojocid, com interesse em técnica, defesa pessoal e condicionamento. Quais são as turmas e horários disponíveis?")}<p class="audience-note">Consulte a equipe sobre turmas, horários e acompanhamento disponível.</p></div></section>'
 else:
  body+='<section class="wrap audience-callout"><p class="eyebrow">Treinamento adulto</p><h2>Técnica e<br>condicionamento físico.</h2><p>Conheça o boxe e converse com a equipe sobre seu objetivo e nível de experiência. O treinamento funcional é uma atividade independente, realizada separadamente das aulas de boxe.</p><a class="secondary-button" href="/#adultos">Conheça o pilar adulto ↗</a><a class="text-link" href="/#funcional">Conheça a atividade de treinamento funcional ↗</a></section>'
 body+=gallery(related,'Na modalidade')
